/// Masked body for an enhancer name, or `None` if unknown.
pub fn blob(name: &str) -> Option<&'static [u8]> {
    match name {
        "safeArea" => Some(SAFE_AREA_ENC),
        "keyboard" => Some(KEYBOARD_ENC),
        "autoplay" => Some(AUTOPLAY_ENC),
        "chromeTrim" => Some(CHROME_TRIM_ENC),
        _ => None,
    }
}
